UPDATE assistant_agent_wait_condition
SET status = #{status}, current_snapshot_json = #{snapshotJson},
    last_check_time = #{checkTime}, satisfied_time = #{satisfiedTime},
    check_count = check_count + 1, version = version + 1,
    update_time = #{checkTime}
WHERE id = #{id}
  AND status IN ('WAITING', 'PARTIALLY_SATISFIED')
  AND version = #{expectedVersion}

